def gen(rng):
    def fmt(h):
        return str(len(h)) + '\n' + ' '.join(map(str, h))
    L = 10**9
    tests = [fmt([7]), fmt([3, 3]), fmt([1, 2]), fmt([2, 1]), fmt([4, 2, 3, 1]), fmt([1, 3, 2, 4, 4]), fmt([5, 5, 5, 5]),
             fmt([L, 1, L, 1, L])]
    for n in (3, 5, 8, 12, 20, 40):
        for hi in (3, 10, 1000):
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(1, L) for _ in range(N)]))
    tests.append(fmt(list(range(N, 0, -1))))
    tests.append(fmt(list(range(1, N + 1))))
    tests.append(fmt([rng.randint(1, 5) for _ in range(N)]))
    tests.append(fmt([L] * N))
    return tests
